//! Source map positions of code generated by transforms.

use std::path::Path;

use oxc_allocator::Allocator;
use oxc_codegen::{Codegen, CodegenOptions};
use oxc_parser::Parser;
use oxc_semantic::SemanticBuilder;
use oxc_span::SourceType;
use oxc_transformer::{DecoratorOptions, ESTarget, TransformOptions, Transformer};

/// A source map token: generated `(line, column)` and original `(line, column)`.
type Token = ((u32, u32), (u32, u32));

/// Transform `source` and print it with a source map.
fn transform(
    source: &str,
    source_type: SourceType,
    options: &TransformOptions,
) -> (String, Vec<Token>) {
    let allocator = Allocator::default();
    let mut program = Parser::new(&allocator, source, source_type).parse().program;
    let scoping = SemanticBuilder::new().build(&program).semantic.into_scoping();
    let ret = Transformer::new(&allocator, Path::new(""), options)
        .build_with_scoping(scoping, &mut program);
    assert!(ret.diagnostics.is_empty(), "{:?}", ret.diagnostics);
    let ret = Codegen::new()
        .with_options(CodegenOptions {
            source_map_path: Some("test.js".into()),
            ..CodegenOptions::default()
        })
        .build(&program);
    let tokens = ret
        .map
        .unwrap()
        .get_tokens()
        .map(|t| ((t.get_dst_line(), t.get_dst_col()), (t.get_src_line(), t.get_src_col())))
        .collect();
    (ret.code, tokens)
}

/// 0-based `(line, column)` of the first occurrence of `needle` in `text`.
fn position(text: &str, needle: &str) -> (u32, u32) {
    let offset = text.find(needle).unwrap_or_else(|| panic!("{needle:?} not found in\n{text}"));
    let line_start = text[..offset].rfind('\n').map_or(0, |i| i + 1);
    let line = text[..offset].matches('\n').count();
    (u32::try_from(line).unwrap(), u32::try_from(offset - line_start).unwrap())
}

/// Original position of the generated `(line, column)`, looked up like a source map consumer:
/// the last mapping at or before `column` on that line.
fn original(tokens: &[Token], (line, column): (u32, u32)) -> Option<(u32, u32)> {
    tokens
        .iter()
        .filter(|((dst_line, dst_col), _)| *dst_line == line && *dst_col <= column)
        .max_by_key(|((_, dst_col), _)| *dst_col)
        .map(|&(_, src)| src)
}

/// Assert that each generated snippet maps to the original snippet paired with it.
fn assert_maps(source: &str, code: &str, tokens: &[Token], pairs: &[(&str, &str)]) {
    for &(generated, expected) in pairs {
        assert_eq!(
            original(tokens, position(code, generated)),
            Some(position(source, expected)),
            "`{generated}` should map to `{expected}`\n{code}"
        );
    }
}

/// The storage, getter, setter and their bodies generated for an auto-accessor map to it:
/// the elements to the accessor, the statements in the bodies to its key.
#[test]
fn lowered_auto_accessor() {
    let source = "class C {\n  @dec accessor x = 1;\n  static accessor #y = 2;\n}\n";
    let options = TransformOptions {
        decorator: DecoratorOptions { legacy: true, ..DecoratorOptions::default() },
        ..TransformOptions::from(ESTarget::ES2022)
    };
    let (code, tokens) = transform(source, SourceType::ts(), &options);
    assert_maps(
        source,
        &code,
        &tokens,
        &[
            ("#_x_accessor_storage = 1", "@dec accessor x"),
            ("get x()", "@dec accessor x"),
            ("return this.#_x_accessor_storage", "x = 1"),
            ("set x(value)", "@dec accessor x"),
            ("x(value)", "x = 1"),
            ("this.#_x_accessor_storage = value", "x = 1"),
            ("static #_y_accessor_storage = 2", "static accessor #y"),
            ("static get #y()", "static accessor #y"),
            ("return C.#_y_accessor_storage", "#y = 2"),
            ("static set #y(value)", "static accessor #y"),
            ("C.#_y_accessor_storage = value", "#y = 2"),
        ],
    );
}

/// Field initializers moved out of the class by class-properties map to their fields.
#[test]
fn lowered_class_fields() {
    let source = "class C {\n  x = 1;\n  #y = 2;\n  static z = C;\n}\n";
    let (code, tokens) =
        transform(source, SourceType::mjs(), &TransformOptions::from(ESTarget::ES2021));
    assert_maps(
        source,
        &code,
        &tokens,
        &[
            ("_defineProperty(this, \"x\"", "x = 1"),
            ("_classPrivateFieldInitSpec(this", "#y = 2"),
            ("_defineProperty(C, \"z\"", "static z"),
        ],
    );
}
